from solution import filter_integers
import pytest
from hypothesis import given
import hypothesis.strategies as st


def ref_filter(values):
    # Obviously correct reference: exact type int only.
    # bool is a distinct type (type(True) is bool, not int),
    # so booleans are not "integers" for filtering purposes.
    return [x for x in values if type(x) is int]


def test_spec_example_1():
    assert filter_integers(['a', 3.14, 5]) == [5]


def test_spec_example_2():
    assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]


def test_booleans_are_not_integers():
    assert filter_integers([True, False, 1, 2]) == [1, 2]


def test_only_booleans_gives_empty():
    assert filter_integers([True, False]) == []


def test_bool_mixed_with_other_types():
    assert filter_integers([True, 'a', 3.14, False, 0, 1, None, {}, []]) == [0, 1]


def test_empty_list():
    assert filter_integers([]) == []


def test_integer_valued_floats_excluded():
    assert filter_integers([1.0, 2.0, 3, 4.0]) == [3]
    assert filter_integers([float(5)]) == []


def test_result_contains_only_exact_ints():
    assert all(type(x) is int for x in filter_integers([True, False, 1, "2", 3.0, None]))


@given(st.lists(st.one_of(
    st.integers(min_value=-10**6, max_value=10**6),
    st.booleans(),
    st.floats(allow_nan=False, allow_infinity=False),
    st.text(max_size=5),
    st.none(),
    st.just([]),
    st.just({}),
), max_size=20))
def test_property_matches_exact_type_reference(values):
    assert filter_integers(values) == ref_filter(values)


@given(st.lists(st.one_of(
    st.integers(min_value=-1000, max_value=1000),
    st.booleans(),
    st.floats(allow_nan=False, allow_infinity=False),
    st.text(max_size=5),
    st.none(),
), max_size=20))
def test_property_output_only_exact_ints(values):
    result = filter_integers(values)
    assert all(type(x) is int for x in result)


@given(st.lists(st.one_of(
    st.integers(min_value=-1000, max_value=1000),
    st.booleans(),
    st.floats(allow_nan=False, allow_infinity=False),
    st.text(max_size=5),
    st.none(),
), max_size=20))
def test_property_preserves_order_and_values(values):
    result = filter_integers(values)
    expected = [x for x in values if type(x) is int]
    assert result == expected
    # order preserved: result is subsequence of input
    it = iter(values)
    for r in result:
        for v in it:
            if v is r or (type(v) is int and v == r):
                break
        else:
            assert False, "order not preserved"


@given(st.lists(st.integers(min_value=-10**9, max_value=10**9), max_size=20))
def test_property_all_ints_identity(values):
    result = filter_integers(values)
    assert result == values
    assert result is not values


@given(st.lists(st.one_of(st.text(max_size=5), st.floats(allow_nan=False, allow_infinity=False), st.none()), max_size=20))
def test_property_no_ints_gives_empty(values):
    # no exact ints in input (avoid accidental ints); filter text/float/None
    # floats strategy could produce integer-valued floats but they are still floats
    assert filter_integers(values) == []


def test_does_not_mutate_input():
    values = [1, True, 'a', 2, False, 3.14]
    snapshot = list(values)
    filter_integers(values)
    assert values == snapshot


def test_negative_zero_and_large_ints():
    vals = [-5, 0, -0, 10**100, -(10**100), True, False]
    assert filter_integers(vals) == [-5, 0, 0, 10**100, -(10**100)]
